import{_ as t,o as a,c as d,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Tenant API v1 — Leave Management","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Leave Management | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-leave-management"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Leave Management | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-leave-management"}]]},"headers":[],"relativePath":"api/tenant-v1-leave-management.md","filePath":"api/tenant-v1-leave-management.md","lastUpdated":1787327680000}'),c={name:"api/tenant-v1-leave-management.md"};function n(r,e,l,s,i,v){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="tenant-api-v1-—-leave-management" tabindex="-1">Tenant API v1 — Leave Management <a class="header-anchor" href="#tenant-api-v1-—-leave-management" aria-label="Permalink to &quot;Tenant API v1 — Leave Management&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:leave-management</code>, plus <code>can:leave-management.*</code>.</p><h2 id="leave-types" tabindex="-1">Leave types <a class="header-anchor" href="#leave-types" aria-label="Permalink to &quot;Leave types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/leave-types</code></td><td><code>leave-management.view</code></td></tr><tr><td>POST</td><td><code>/leave-types</code></td><td><code>leave-management.create</code></td></tr><tr><td>GET</td><td><code>/leave-types/{leaveType}</code></td><td><code>leave-management.view</code></td></tr><tr><td>PUT</td><td><code>/leave-types/{leaveType}</code></td><td><code>leave-management.update</code></td></tr><tr><td>DELETE</td><td><code>/leave-types/{leaveType}</code></td><td><code>leave-management.delete</code></td></tr><tr><td>POST</td><td><code>/leave-types/{leaveType}/restore</code></td><td><code>leave-management.restore</code></td></tr><tr><td>DELETE</td><td><code>/leave-types/{leaveType}/force</code></td><td><code>leave-management.force.delete</code></td></tr></tbody></table><p>Create body: <code>name</code>, <code>code</code> (required, unique per tenant), optional <code>is_paid</code>, <code>annual_allowance</code>, <code>description</code>, <code>is_active</code>.</p><h2 id="leave-balances" tabindex="-1">Leave balances <a class="header-anchor" href="#leave-balances" aria-label="Permalink to &quot;Leave balances&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/leave-balances</code></td><td><code>leave-management.view</code></td></tr><tr><td>POST</td><td><code>/leave-balances</code></td><td><code>leave-management.create</code> (upsert)</td></tr><tr><td>GET</td><td><code>/leave-balances/{leaveBalance}</code></td><td><code>leave-management.view</code></td></tr><tr><td>PUT</td><td><code>/leave-balances/{leaveBalance}</code></td><td><code>leave-management.update</code></td></tr><tr><td>DELETE</td><td><code>/leave-balances/{leaveBalance}</code></td><td><code>leave-management.delete</code></td></tr><tr><td>POST</td><td><code>/leave-balances/{leaveBalance}/restore</code></td><td><code>leave-management.restore</code></td></tr><tr><td>DELETE</td><td><code>/leave-balances/{leaveBalance}/force</code></td><td><code>leave-management.force.delete</code></td></tr></tbody></table><h3 id="post-leave-balances-upsert" tabindex="-1">POST <code>/leave-balances</code> (upsert) <a class="header-anchor" href="#post-leave-balances-upsert" aria-label="Permalink to &quot;POST `/leave-balances` (upsert)&quot;">​</a></h3><p>Body: <code>employee_id</code>, <code>leave_type_id</code>, <code>year</code> (2000–2100), <code>entitled</code> (required), optional <code>used</code>, <code>remaining</code>. Remaining is synced from entitled − used when not supplied.</p><h2 id="leave-requests" tabindex="-1">Leave requests <a class="header-anchor" href="#leave-requests" aria-label="Permalink to &quot;Leave requests&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Permission</th></tr></thead><tbody><tr><td>GET</td><td><code>/leave-requests</code></td><td><code>leave-management.view</code></td></tr><tr><td>POST</td><td><code>/leave-requests</code></td><td><code>leave-management.create</code></td></tr><tr><td>GET</td><td><code>/leave-requests/{leaveRequest}</code></td><td><code>leave-management.view</code></td></tr><tr><td>PUT</td><td><code>/leave-requests/{leaveRequest}</code></td><td><code>leave-management.update</code></td></tr><tr><td>POST</td><td><code>/leave-requests/{leaveRequest}/submit</code></td><td><code>leave-management.update</code></td></tr><tr><td>POST</td><td><code>/leave-requests/{leaveRequest}/approve</code></td><td><code>leave-management.approve</code></td></tr><tr><td>POST</td><td><code>/leave-requests/{leaveRequest}/reject</code></td><td><code>leave-management.approve</code></td></tr><tr><td>POST</td><td><code>/leave-requests/{leaveRequest}/cancel</code></td><td><code>leave-management.update</code></td></tr><tr><td>DELETE</td><td><code>/leave-requests/{leaveRequest}</code></td><td><code>leave-management.delete</code></td></tr><tr><td>POST</td><td><code>/leave-requests/{leaveRequest}/restore</code></td><td><code>leave-management.restore</code></td></tr><tr><td>DELETE</td><td><code>/leave-requests/{leaveRequest}/force</code></td><td><code>leave-management.force.delete</code></td></tr></tbody></table><p>Create body: <code>employee_id</code>, <code>leave_type_id</code>, <code>start_date</code>, <code>end_date</code> (required); optional <code>days</code> (min 0.5), <code>reason</code>. Status starts as <code>draft</code>.</p><p><strong>Self-service:</strong> non-admin actors may only create/update/submit/cancel for their linked active employee. Admin and superadmin may create on behalf of others. Managers create for self but may approve/reject others. Index is scoped to the actor’s employee unless they can approve or create for others.</p><h3 id="post-leave-requests-id-approve" tabindex="-1">POST <code>/leave-requests/{id}/approve</code> <a class="header-anchor" href="#post-leave-requests-id-approve" aria-label="Permalink to &quot;POST `/leave-requests/{id}/approve`&quot;">​</a></h3><p>Body (optional fields):</p><table tabindex="0"><thead><tr><th>Field</th><th>Rules</th></tr></thead><tbody><tr><td><code>deduct_salary</code></td><td>boolean; default = <code>!leaveType.is_paid</code> when omitted</td></tr><tr><td><code>review_notes</code></td><td>string, max 5000; <strong>required</strong> when <code>deduct_salary</code> differs from the default</td></tr></tbody></table><p>On success, <code>deduct_salary</code> is stored on the approved request (used by Payroll period calculation).</p><h3 id="post-leave-requests-id-reject" tabindex="-1">POST <code>/leave-requests/{id}/reject</code> <a class="header-anchor" href="#post-leave-requests-id-reject" aria-label="Permalink to &quot;POST `/leave-requests/{id}/reject`&quot;">​</a></h3><p>Body: <code>review_notes</code> (<strong>required</strong>, string, max 5000).</p><p>Workflow: <code>draft → pending → approved|rejected</code>; <code>draft|pending → cancelled</code>. Approve applies days to the leave balance for the request’s start year.</p><p>Resource includes <code>deduct_salary</code> (nullable until approved) and nested <code>leave_type.is_paid</code>.</p>',22)])])}const u=t(c,[["render",n]]);export{m as __pageData,u as default};
